select from club_role_assignment where club_id = #{clubId} and status = 'ACTIVE' and (expires_at is null or expires_at > #{now})
and scope_type = 'EVENT' and scope_id = #{activityId}
order by scope_type asc, scope_id asc, id asc

select 
from club_role_assignment
where club_id = #{clubId} and target_member_id = #{targetMemberId}
  and scope_type = #{scopeType} and scope_id = #{scopeId}
  and status = 'ACTIVE' and (expires_at is null or expires_at > #{now})
limit 1

mapper.update:
update club_role_assignment
set status = 'EXPIRED', version = version + 1,
    update_by = #{updateBy}, update_time = #{now}
where club_id = #{clubId} and target_member_id = #{targetMemberId}
  and scope_type = #{scopeType} and scope_id = #{scopeId}
  and status = 'ACTIVE' and expires_at is not null and expires_at <= #{now}

update club_role_assignment
set status = 'REVOKED', revoked_by_member_id = #{revokedByMemberId},
    revoked_at = now(), revoke_reason = #{revokeReason}, version = version + 1,
    update_by = #{updateBy}, update_time = now()
where id = #{id} and club_id = #{clubId}
  and status = 'ACTIVE' and version = #{expectedVersion}

update club_role_assignment
set status = 'REVOKED', revoked_by_member_id = #{revokedByMemberId},
    revoked_at = #{now}, revoke_reason = #{revokeReason}, version = version + 1,
    update_by = #{updateBy}, update_time = #{now}
where club_id = #{clubId} and target_member_id = #{targetMemberId}
  and status = 'ACTIVE'
